// ── CSV (RFC 4180) with spreadsheet formula-injection protection ─────────────
//
// Pure and dependency-free. A cell is either:
//   · a NUMBER — written raw (finite numbers only; 2 decimals for money is the
//     caller's choice via csvMoney). Numbers are generated by our own code from
//     validated figures, so a leading "-" on a negative amount is a number, not
//     a formula, and must stay one.
//   · anything else — converted to text, sanitised, and ALWAYS quoted.
//
// Text sanitising (OWASP "CSV Injection"):
//   1. Line breaks are normalised to "\n" (kept, inside quotes).
//   2. Other C0 control characters and DEL are removed — except TAB, which is
//      handled by rule 3 when it leads.
//   3. If the text — after skipping any leading whitespace, control, zero-width
//      or bidi-format characters that could hide what follows — starts with a
//      formula trigger (= + - @, or their full-width forms), or if the text
//      itself starts with TAB or CR, it is prefixed with a single quote ('), so
//      spreadsheet applications treat the cell as text.
//   4. Double quotes are doubled and the cell is wrapped in double quotes.

const FORMULA_TRIGGERS = new Set(['=', '+', '-', '@', '\uFF1D', '\uFF0B', '\uFF0D', '\uFF20'])

// Characters that can conceal a trigger: whitespace (incl. NBSP and the
// Unicode space separators), C0/C1 controls, zero-width and bidi formatting
// characters, and the BOM.
// eslint-disable-next-line no-control-regex
const CONCEALING = /^[\s\u0000-\u001F\u007F-\u009F\u00A0\u1680\u180E\u2000-\u200F\u2028-\u202F\u205F-\u206F\u3000\uFEFF]*/

export function isFormulaLike(text) {
  const s = String(text ?? '')
  if (s.startsWith('\t') || s.startsWith('\r')) return true
  const rest = s.replace(CONCEALING, '')
  return rest.length > 0 && FORMULA_TRIGGERS.has(rest[0])
}

export function sanitizeCsvText(value) {
  let s = String(value ?? '')
  s = s.replace(/\r\n?/g, '\n')
  // Remove control characters except TAB (\u0009) and LF (\u000A).
  // eslint-disable-next-line no-control-regex
  s = s.replace(/[\u0000-\u0008\u000B-\u001F\u007F]/g, '')
  if (isFormulaLike(s)) s = `'${s}`
  return s
}

export function csvCell(value) {
  if (typeof value === 'number') {
    return Number.isFinite(value) ? String(value) : '""'
  }
  const s = sanitizeCsvText(value)
  return `"${s.replace(/"/g, '""')}"`
}

// A money amount as a fixed 2-decimal NUMBER string (no symbol, no grouping),
// so a spreadsheet reads it as a number. Returns a marker object csvRows
// recognises; non-finite input becomes null (the caller decides the label).
export function csvMoney(n) {
  const v = typeof n === 'number' ? n : Number(n)
  if (!Number.isFinite(v)) return null
  // -0 → 0 so a genuine zero never exports as "-0.00".
  const fixed = (Math.round((v + Number.EPSILON) * 100) / 100).toFixed(2)
  return { csvNumber: fixed === '-0.00' ? '0.00' : fixed }
}

function cellOut(value) {
  if (value && typeof value === 'object' && typeof value.csvNumber === 'string') return value.csvNumber
  return csvCell(value)
}

// Rows (arrays of cells) → one CSV string, CRLF line endings, trailing CRLF.
export function csvRows(rows) {
  return (rows ?? []).map(r => (r ?? []).map(cellOut).join(',')).join('\r\n') + '\r\n'
}

// A filesystem-safe slug for a filename part: ASCII letters, digits and single
// hyphens; never empty (falls back to `fallback`).
export function filenameSlug(text, fallback = 'project', maxLength = 60) {
  const slug = String(text ?? '')
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, maxLength)
    .replace(/-+$/g, '')
  return slug || fallback
}
